const pending = new Map();

socket.addEventListener('message', (event) => {
  const tick = JSON.parse(event.data);
  pending.set(tick.symbol, tick.price);
});

setInterval(() => {
  if (pending.size === 0) return;
  for (const [symbol, price] of pending) {
    chart.data.datasets[index[symbol]].data.push(price);
  }
  pending.clear();
  chart.update('none');
}, 500);

def cached_article(slug):
    key = f'article:{slug}'
    hit = redis.get(key)
    if hit:
        payload = json.loads(hit)
        if payload['version'] >= current_version(slug):
            return payload['data']

    row = Article.objects.get(slug=slug)
    payload = {'version': row.updated_at.timestamp(), 'data': serialize(row)}
    redis.setex(key, 300, json.dumps(payload))
    return payload['data']

export async function GET() {
  const encoder = new TextEncoder();
  const stream = new ReadableStream({
    async start(controller) {
      for await (const chunk of generate()) {
        controller.enqueue(encoder.encode(`data: ${JSON.stringify(chunk)}\n\n`));
      }
      controller.close();
    },
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      'X-Accel-Buffering': 'no',
    },
  });
}
